insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Comissão, no exame para obtenção de dados reveladores da personalidade, observando a ética profissional e tendo sempre presentes peças ou informações do processo, poderá entrevistar pessoas; requisitar, de repartições ou estabelecimentos privados, dados e informações sobre o condenado; e realizar outras diligências e exames necessários.', '["Entrevistar pessoas.","Requisitar dados e informações.","Outras diligências e exames."]'::jsonb, '["Observância da ética profissional."]'::jsonb, 'A Comissão entrevista familiares e requisita informações do condenado.', '["Assertiva que impede a Comissão de requisitar dados a estabelecimentos privados erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-9' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cc92ceb1f0956ceef755dc3d1adcda5503d63b143db50e6f6f9aff8d4eb2bc5b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado à pena de reclusão em regime inicial fechado será submetido obrigatoriamente à identificação do perfil genético, mediante extração de DNA, por técnica adequada e indolor, por ocasião do ingresso no estabelecimento prisional. O perfil será armazenado em banco de dados sigiloso, com garantias de proteção de dados genéticos. A autoridade policial poderá requerer ao juiz, em inquérito instaurado, o acesso ao banco. O titular tem acesso aos seus dados e à cadeia de custódia. Quem não foi submetido à coleta no ingresso deverá sê-lo durante a pena. A amostra só pode servir à identificação pelo perfil genético, vedada a fenotipagem genética, e é descartada após a identificação, guardando-se material para nova perícia. A coleta é feita por agente treinado, e o laudo por perito oficial. Nos crimes hediondos e equiparados, os vestígios devem ser processados, se possível, em até 30 dias.', '["Coleta obrigatória de DNA do condenado à reclusão em regime inicial fechado.","Banco de dados sigiloso.","Vedada a fenotipagem genética.","Laudo por perito oficial.","Hediondos: processamento em até 30 dias."]'::jsonb, '["ATUALIZAÇÃO: redação dada pelo Pacote Anticrime.","Recusar a coleta é FALTA GRAVE (art. 50, VIII)."]'::jsonb, 'Ao ingressar no presídio, o condenado em regime inicial fechado tem o DNA coletado.', '["Assertiva que autoriza a fenotipagem genética com a amostra coletada erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 50, VIII"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-9-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd5e3afbe6d8d49b2d5b87c6d3d3d3d40bfd396e0b5d8aa828bbe3c1840e76979'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A assistência ao preso e ao internado é dever do Estado, objetivando prevenir o crime e orientar o retorno à convivência em sociedade. A assistência estende-se ao egresso.', '["Dever do Estado.","Prevenir o crime e orientar o retorno à sociedade.","Estende-se ao egresso."]'::jsonb, '["Alcança o EGRESSO."]'::jsonb, 'O egresso continua recebendo orientação do Estado.', '["Assertiva que encerra a assistência com a saída da prisão erra: ela se estende ao egresso."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
