insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A assistência à saúde do preso e do internado, de caráter preventivo e curativo, compreenderá atendimento médico, farmacêutico e odontológico. Quando o estabelecimento não estiver aparelhado, a assistência será prestada em outro local, mediante autorização da direção. Será assegurado acompanhamento médico à mulher, principalmente no pré-natal e no pós-parto, extensivo ao recém-nascido, e tratamento humanitário à gestante durante os atos médico-hospitalares do parto e no puerpério, cabendo ao poder público a assistência integral à sua saúde e à do recém-nascido.', '["Atendimento médico, farmacêutico e odontológico.","Atendimento externo se a unidade não tiver estrutura.","Pré-natal, pós-parto e recém-nascido.","Tratamento humanitário no parto e no puerpério."]'::jsonb, '["ATUALIZAÇÃO: o §4º (tratamento humanitário no parto) foi incluído por lei posterior.","Saúde com caráter PREVENTIVO e CURATIVO."]'::jsonb, 'A presa gestante tem acompanhamento no pré-natal e tratamento humanitário no parto.', '["Assertiva que restringe a assistência à saúde ao caráter curativo erra: é preventiva e curativa."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-14' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '42f632e9e7dd67be986ee9cf4f88be62c5aa3a5ba8b12376dd4e0b84cad47f99'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
