from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-15' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '37d9cebebfa217ae5cf2e96da7735177ec0eb05ab81fa323419e0e1fd211108c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
