insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As Unidades da Federação deverão ter serviços de assistência jurídica, integral e gratuita, pela Defensoria Pública, dentro e fora dos estabelecimentos penais, prestando-lhe auxílio estrutural, pessoal e material. Em todos os estabelecimentos haverá local apropriado para o atendimento pelo Defensor Público. Fora dos estabelecimentos serão implementados Núcleos Especializados da Defensoria Pública para assistência integral e gratuita aos réus, sentenciados em liberdade, egressos e seus familiares sem recursos.', '["Defensoria Pública presta a assistência jurídica integral e gratuita.","Local apropriado em todos os estabelecimentos.","Núcleos Especializados fora das unidades."]'::jsonb, '["Alcança réus, sentenciados em liberdade, egressos e seus familiares."]'::jsonb, 'A unidade prisional tem sala para o atendimento do Defensor Público.', '["Assertiva que restringe a Defensoria ao atendimento dentro das unidades prisionais erra: há Núcleos Especializados fora delas."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
