insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O ensino médio, regular ou supletivo, com formação geral ou educação profissional de nível médio, será implantado nos presídios, em obediência ao preceito constitucional de sua universalização. O ensino integrar-se-á ao sistema estadual e municipal e será mantido com o apoio da União. Os sistemas de ensino oferecerão cursos supletivos de educação de jovens e adultos, e os entes incluirão em seus programas de educação a distância e novas tecnologias o atendimento aos presos.', '["Ensino médio nos presídios.","Integração ao sistema estadual e municipal, com apoio da União.","Educação de jovens e adultos e educação a distância."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O presídio oferece ensino médio supletivo.', '["Assertiva que exclui o ensino médio dos presídios erra: ele deve ser implantado."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
