select u.id, u.content_sha256, 'O censo penitenciário deverá apurar o nível de escolaridade dos presos e das presas; a existência de cursos fundamentais e médios e o número de atendidos; a implementação de cursos profissionais e o número de atendidos; a existência de bibliotecas e as condições de seu acervo; e outros dados relevantes para o aprimoramento educacional.', '["Escolaridade dos presos.","Cursos fundamentais, médios e profissionais.","Bibliotecas e acervos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O censo apura quantos presos frequentam cursos.', '["Assertiva que exclui as bibliotecas do censo penitenciário erra."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-21-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'fd3dfc5a3f7fdaf8b91efdcee7a6ab0bac3134f05d7655301e00096f8a952505'
