select u.id, u.content_sha256, 'A assistência social tem por finalidade amparar o preso e o internado e prepará-los para o retorno à liberdade.', '["Amparar o preso e preparar o retorno à liberdade."]'::jsonb, '["Dupla finalidade."]'::jsonb, 'O assistente social prepara o preso para a liberdade.', '["Assertiva que limita a assistência social à época de soltura erra."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
