insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A assistência religiosa, com liberdade de culto, será prestada aos presos e aos internados, permitindo-se-lhes a participação nos serviços organizados no estabelecimento e a posse de livros de instrução religiosa. No estabelecimento haverá local apropriado para os cultos. Nenhum preso ou internado poderá ser obrigado a participar de atividade religiosa.', '["Liberdade de culto.","Local apropriado para cultos.","Vedada a obrigatoriedade."]'::jsonb, '["Nenhum preso é OBRIGADO a participar."]'::jsonb, 'O preso participa do culto de sua religião, por vontade própria.', '["Assertiva que obriga o preso a participar de atividade religiosa erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-24' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '111889a65b2331c0c6e3b86dacc6a5ab656dd72ef411ce78bdd363e065933f39'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A assistência ao egresso consiste na orientação e apoio para reintegrá-lo à vida em liberdade e na concessão, se necessário, de alojamento e alimentação, em estabelecimento adequado, pelo prazo de dois meses. O prazo poderá ser prorrogado uma única vez, comprovado, por declaração do assistente social, o empenho na obtenção de emprego.', '["Orientação e apoio.","Alojamento e alimentação por dois meses.","Prorrogação por uma única vez."]'::jsonb, '["Dois meses, prorrogáveis UMA vez."]'::jsonb, 'O egresso recebe alojamento por dois meses e, se estiver buscando emprego, mais um período.', '["Assertiva que permite prorrogações sucessivas do alojamento erra: é uma única vez."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-25' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f55ce3d98b4986a792d64b882adefcf66fd595e2154ea48baa8b0a71414fdc18'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
