insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Considera-se egresso para os efeitos da Lei o liberado definitivo, pelo prazo de um ano a contar da saída do estabelecimento, e o liberado condicional, durante o período de prova.', '["Liberado definitivo: um ano.","Liberado condicional: durante o período de prova."]'::jsonb, '["Egresso definitivo: UM ANO."]'::jsonb, 'Quem cumpriu a pena e saiu há seis meses ainda é egresso.', '["Assertiva que fixa em dois anos o prazo de egresso do liberado definitivo erra: é um ano."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
