select u.id, u.content_sha256, 'O serviço de assistência social colaborará com o egresso para a obtenção de trabalho.', '["Colaboração na obtenção de trabalho."]'::jsonb, '["Apoio à inserção laboral."]'::jsonb, 'O serviço social indica vagas ao egresso.', '["Assertiva que dispensa a ajuda do serviço social na obtenção de trabalho erra."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
