insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trabalho do condenado, como dever social e condição de dignidade humana, terá finalidade educativa e produtiva. Aplicam-se à organização e aos métodos de trabalho as precauções relativas à segurança e à higiene. O trabalho do preso não está sujeito ao regime da Consolidação das Leis do Trabalho.', '["Dever social e condição de dignidade.","Finalidade educativa e produtiva.","Não se sujeita à CLT."]'::jsonb, '["O trabalho do preso NÃO está sob a CLT."]'::jsonb, 'O preso que trabalha na oficina da unidade não tem vínculo celetista.', '["Assertiva que submete o trabalho do preso à CLT erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-28' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b95850ac13a3c9063e5b799671cf16f954b81924342c12c0e50128183bad48f6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trabalho do preso será remunerado, mediante prévia tabela, não podendo ser inferior a três quartos do salário mínimo. O produto da remuneração deverá atender à indenização dos danos causados pelo crime, desde que determinados judicialmente e não reparados por outros meios; à assistência à família; a pequenas despesas pessoais; e ao ressarcimento ao Estado das despesas com a manutenção do condenado. A parte restante será depositada para constituição do pecúlio, em caderneta de poupança, entregue ao condenado quando posto em liberdade.', '["Remuneração não inferior a três quartos do salário mínimo.","Destinação: indenização, família, despesas pessoais e ressarcimento ao Estado.","Pecúlio em caderneta de poupança."]'::jsonb, '["Mínimo de TRÊS QUARTOS do salário mínimo."]'::jsonb, 'Parte do salário do preso vai para o pecúlio, entregue na soltura.', '["Assertiva que fixa o mínimo em um salário mínimo erra: são três quartos."]'::jsonb, '[{"termo":"Pecúlio","significado":"Reserva de dinheiro do preso, entregue na liberdade."}]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-29' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '162d0911b531b4d2e41d4ff00766acd232eb1d9cc8656ce246fe454fd49f9076'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
