insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder disciplinar, na execução da pena privativa de liberdade, será exercido pela autoridade administrativa conforme as disposições regulamentares.', '["Poder disciplinar exercido pela autoridade administrativa."]'::jsonb, '["Autoridade ADMINISTRATIVA."]'::jsonb, 'O diretor aplica a sanção disciplinar prevista no regulamento.', '["Assertiva que atribui ao juiz o poder disciplinar na pena privativa erra: é da autoridade administrativa."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-47' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '43937d09ee54d844e13ff42a3ff1160efe0fb161e0abdea165f080e71a8924b0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
