insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As faltas disciplinares classificam-se em leves, médias e graves. A legislação local especificará as leves e médias, bem assim as respectivas sanções. Pune-se a tentativa com a sanção correspondente à falta consumada.', '["Faltas leves, médias e graves.","Leves e médias: legislação local.","Tentativa punida como falta consumada."]'::jsonb, '["As faltas GRAVES estão na lei federal; leves e médias, na legislação local."]'::jsonb, 'A tentativa de fuga é punida como a fuga.', '["Assertiva que não pune a tentativa de falta disciplinar erra: pune-se como a falta consumada."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-49' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0544f668c3916004ccdfe719edf41984f412561f08f6cc3152d5cbf5f6706dbb'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
