insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constituem sanções disciplinares a advertência verbal; a repreensão; a suspensão ou restrição de direitos; o isolamento na própria cela ou em local adequado, nos estabelecimentos com alojamento coletivo; e a inclusão no regime disciplinar diferenciado.', '["Advertência verbal.","Repreensão.","Suspensão ou restrição de direitos.","Isolamento.","Regime disciplinar diferenciado."]'::jsonb, '["Cinco sanções disciplinares."]'::jsonb, 'O preso recebe advertência verbal por falta leve.', '["Assertiva que inclui a cela escura entre as sanções erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-53' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8b9e638753e4954b08c1e9d74c2787c3dc0b233a099a697726df0a590b2ab1e4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
