insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O isolamento, a suspensão e a restrição de direitos não poderão exceder a trinta dias, ressalvada a hipótese do regime disciplinar diferenciado. O isolamento será sempre comunicado ao juiz da execução.', '["Limite de trinta dias.","Exceção: RDD.","Comunicação do isolamento ao juiz."]'::jsonb, '["Limite de TRINTA dias, exceto no RDD."]'::jsonb, 'O isolamento por falta disciplinar não passa de trinta dias.', '["Assertiva que fixa em sessenta dias o limite do isolamento erra: são trinta."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-58' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f148e83a8445d2f445a588cf01f5a3ab13952cb30d77b9a5768c6775f21c858e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
