insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Praticada a falta disciplinar, deverá ser instaurado o procedimento para sua apuração, conforme regulamento, assegurado o direito de defesa. A decisão será motivada.', '["Procedimento de apuração.","Direito de defesa.","Decisão motivada."]'::jsonb, '["Defesa e motivação são obrigatórias."]'::jsonb, 'O preso se defende antes de ser punido.', '["Assertiva que dispensa a defesa na apuração da falta disciplinar erra."]'::jsonb, '[]'::jsonb, '["Art. 60"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-59' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '74247e514e6147b3d4d42082db92d4dcdd4c9cea615ac7da92ddcde10b527fd1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
