insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São órgãos da execução penal o Conselho Nacional de Política Criminal e Penitenciária; o Juízo da Execução; o Ministério Público; o Conselho Penitenciário; os Departamentos Penitenciários; o Patronato; o Conselho da Comunidade; e a Defensoria Pública.', '["Oito órgãos da execução penal."]'::jsonb, '["A Defensoria Pública é órgão da execução (inciso VIII)."]'::jsonb, 'A Defensoria Pública atua como órgão da execução penal.', '["Assertiva que exclui a Defensoria Pública dos órgãos da execução erra."]'::jsonb, '[]'::jsonb, '["Art. 81-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-61' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'beb16eeaf03a746e72fb65e1cc05ef66826cfd43e1c767dc47671b23ecb616b2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
