insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Conselho Nacional de Política Criminal e Penitenciária, com sede na Capital da República, é subordinado ao Ministério da Justiça.', '["Sede na Capital da República.","Subordinado ao Ministério da Justiça."]'::jsonb, '["Subordinado ao Ministério da Justiça."]'::jsonb, 'O Conselho Nacional funciona em Brasília, ligado ao Ministério da Justiça.', '["Assertiva que subordina o Conselho ao Poder Judiciário erra."]'::jsonb, '[]'::jsonb, '["Art. 63"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-62' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'aa0052af1473884e08326d0460ab2ffffd938ddcb758e7ca15de66c48cb6bfe6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Conselho Nacional de Política Criminal e Penitenciária será integrado por 13 membros designados por ato do Ministério da Justiça, dentre professores e profissionais da área do Direito Penal, Processual Penal, Penitenciário e ciências correlatas, bem como por representantes da comunidade e dos Ministérios da área social. O mandato dos membros tem duração de 2 anos, renovado 1/3 em cada ano.', '["13 membros.","Mandato de 2 anos.","Renovação de 1/3 por ano."]'::jsonb, '["13 membros; mandato de 2 anos; renovação de 1/3 ao ano."]'::jsonb, 'A cada ano, um terço dos membros do Conselho Nacional é renovado.', '["Assertiva que fixa em 4 anos o mandato dos membros do Conselho Nacional erra: são 2 anos."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-63' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd5886fcc648ac97ac63dd91b4ac096695c8892ed13f0b7eba4d80c645aea96b9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao Conselho Nacional de Política Criminal e Penitenciária incumbe propor diretrizes da política criminal; contribuir na elaboração de planos nacionais de desenvolvimento; promover a avaliação periódica do sistema criminal; estimular a pesquisa criminológica; elaborar programa nacional de formação do servidor; estabelecer regras sobre a arquitetura de estabelecimentos penais; estabelecer critérios para a estatística criminal; inspecionar e fiscalizar os estabelecimentos penais; representar ao juiz ou à autoridade administrativa para instauração de sindicância; e representar à autoridade competente para a interdição de estabelecimento penal.', '["Diretrizes de política criminal.","Pesquisa criminológica e estatística criminal.","Inspeção e fiscalização dos estabelecimentos.","Representar pela interdição de estabelecimento."]'::jsonb, '["O Conselho Nacional REPRESENTA pela interdição; quem interdita é o juiz."]'::jsonb, 'O Conselho Nacional representa ao juiz para a interdição de um presídio inadequado.', '["Assertiva que permite ao Conselho Nacional interditar diretamente o estabelecimento erra: ele representa."]'::jsonb, '[]'::jsonb, '["Art. 66, VIII"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-64' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'fe44386252f721e58b135c93938ed4e1ab54dbf14fae337c9a9f7379d6a02c1c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A execução penal competirá ao Juiz indicado na lei local de organização judiciária e, na sua ausência, ao da sentença.', '["Juiz indicado na lei local.","Na falta, o juiz da sentença."]'::jsonb, '["Subsidiariedade: o juiz da sentença."]'::jsonb, 'Na comarca sem vara de execuções, o juiz da sentença conduz a execução.', '["Assertiva que atribui sempre a execução ao juiz da sentença erra: primeiro é o juiz indicado na lei local."]'::jsonb, '[]'::jsonb, '["Art. 66"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-65' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '081fcbd7c39200dc24e830bfbd9150c5971116683aed979165d276d0ec5454c3'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Juiz da execução aplicar aos casos julgados lei posterior que favoreça o condenado; declarar extinta a punibilidade; decidir sobre soma ou unificação de penas, progressão ou regressão de regimes, detração e remição, suspensão condicional da pena, livramento condicional e incidentes da execução; autorizar saídas temporárias; determinar a forma de cumprimento da pena restritiva de direitos, as conversões de penas, a medida de segurança, a desinternação, o cumprimento em outra comarca e a remoção do condenado; decidir sobre a monitoração eletrônica; zelar pelo correto cumprimento da pena; inspecionar mensalmente os estabelecimentos penais; interditar, no todo ou em parte, estabelecimento em condições inadequadas; compor e instalar o Conselho da Comunidade; e emitir anualmente atestado de pena a cumprir.', '["Lei posterior mais benéfica.","Extinção da punibilidade.","Progressão, regressão, detração, remição, livramento condicional.","Saídas temporárias.","Inspeção mensal e interdição de estabelecimentos.","Atestado de pena a cumprir anual."]'::jsonb, '["O juiz inspeciona MENSALMENTE os estabelecimentos.","ATUALIZAÇÃO: o inciso X (atestado de pena a cumprir) foi incluído por lei posterior."]'::jsonb, 'O juiz da execução decide a progressão de regime e autoriza a saída temporária.', '["Assertiva que atribui ao diretor a decisão sobre progressão de regime erra: é do juiz da execução."]'::jsonb, '[]'::jsonb, '["Art. 65"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-66' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0a001da3aef479eef61e1650a35c500691550f3a6a3a564c073cf4ff4e293ee7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério Público fiscalizará a execução da pena e da medida de segurança, oficiando no processo executivo e nos incidentes da execução.', '["Fiscalização da execução.","Atuação no processo executivo e nos incidentes."]'::jsonb, '["Atua como fiscal da execução."]'::jsonb, 'O Promotor acompanha os incidentes da execução.', '["Assertiva que exclui o Ministério Público da execução penal erra."]'::jsonb, '[]'::jsonb, '["Art. 68"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-67' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5019a581a37ae802a0ae3f9d4394ae8dbcf234c0b6e417b2720ecbf0f4b29a0a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe ainda ao Ministério Público fiscalizar a regularidade formal das guias de recolhimento e de internamento; requerer providências para o desenvolvimento do processo executivo, a instauração dos incidentes de excesso ou desvio de execução, a aplicação, a substituição e a revogação de medida de segurança, a conversão de penas, a progressão ou regressão e a revogação da suspensão condicional e do livramento condicional, e a internação e a desinternação; e interpor recursos de decisões proferidas durante a execução. O órgão visitará mensalmente os estabelecimentos penais, registrando sua presença em livro próprio.', '["Fiscalizar as guias.","Requerer incidentes e conversões.","Interpor recursos.","Visita mensal aos estabelecimentos."]'::jsonb, '["Visita MENSAL do MP aos estabelecimentos."]'::jsonb, 'O Promotor visita mensalmente o presídio e registra a presença no livro.', '["Assertiva que dispensa a visita mensal do Ministério Público erra."]'::jsonb, '[]'::jsonb, '["Art. 67"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-68' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '417e40bda33dbbc6f871e4aa40dd6035af5227d4166433a17be5885f05405c59'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Conselho Penitenciário é órgão consultivo e fiscalizador da execução da pena. É integrado por membros nomeados pelo Governador do Estado, do Distrito Federal e dos Territórios, dentre professores e profissionais da área do Direito Penal, Processual Penal, Penitenciário e ciências correlatas, bem como por representantes da comunidade. O mandato dos membros tem a duração de 4 anos.', '["Órgão consultivo e fiscalizador.","Membros nomeados pelo Governador.","Mandato de 4 anos."]'::jsonb, '["Mandato de 4 anos (o do Conselho Nacional é de 2)."]'::jsonb, 'O Governador nomeia os membros do Conselho Penitenciário estadual.', '["Assertiva que fixa em 2 anos o mandato do Conselho Penitenciário erra: são 4 anos."]'::jsonb, '[]'::jsonb, '["Art. 70"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-69' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'bf79ee86afd3bc79c6e0e2ef7c9afa3f4d9771aacb2aa3eb99b02b3096d30fd6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe ao Conselho Penitenciário emitir parecer sobre indulto e comutação de pena, excetuada a hipótese de pedido de indulto com base no estado de saúde do preso; inspecionar os estabelecimentos e serviços penais; apresentar, no 1º trimestre de cada ano, ao Conselho Nacional de Política Criminal e Penitenciária relatório dos trabalhos do exercício anterior; e supervisionar os patronatos e a assistência aos egressos.', '["Parecer sobre indulto e comutação, salvo indulto por saúde.","Inspeção de estabelecimentos.","Relatório anual no 1º trimestre.","Supervisão dos patronatos."]'::jsonb, '["ATUALIZAÇÃO: o parecer sobre indulto por saúde é dispensado pela redação vigente.","Relatório no PRIMEIRO trimestre de cada ano."]'::jsonb, 'O Conselho Penitenciário opina sobre o decreto de indulto.', '["Assertiva que exige parecer do Conselho Penitenciário também no indulto por estado de saúde erra: é a exceção."]'::jsonb, '[]'::jsonb, '["Art. 69"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-70' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '510184411f5f3adb6babd754bf838be82f5f8c610d4b2389dcdb14b0f45ba211'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Departamento Penitenciário Nacional, subordinado ao Ministério da Justiça, é órgão executivo da Política Penitenciária Nacional e de apoio administrativo e financeiro do Conselho Nacional de Política Criminal e Penitenciária.', '["Órgão executivo da política penitenciária.","Apoio ao Conselho Nacional."]'::jsonb, '["DEPEN: órgão EXECUTIVO."]'::jsonb, 'O Depen executa a política penitenciária nacional.', '["Assertiva que atribui ao Depen a função consultiva erra: é executiva."]'::jsonb, '[{"termo":"Depen","significado":"Departamento Penitenciário Nacional."}]'::jsonb, '["Art. 72"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-71' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9b9cdb3074ba849c1d6852b3b56243a0b7697af910fdf9243cb2b6f0929bf245'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São atribuições do Departamento Penitenciário Nacional acompanhar a aplicação das normas de execução penal em todo o território; inspecionar e fiscalizar os estabelecimentos; assistir tecnicamente as Unidades Federativas; colaborar, por convênios, na implantação de estabelecimentos; colaborar na formação de pessoal penitenciário; estabelecer o cadastro nacional de vagas para cumprimento de pena aplicada por outra unidade federativa, especialmente para presos em regime disciplinar; e acompanhar a execução da pena das mulheres beneficiadas pela progressão especial do art. 112, §3º, monitorando sua integração social e a reincidência. Também coordena e supervisiona os estabelecimentos penais e de internamento federais.', '["Acompanhar a execução penal no país.","Inspeção e fiscalização.","Apoio técnico e convênios.","Cadastro nacional de vagas.","Acompanhamento da progressão especial das mulheres.","Supervisão dos estabelecimentos federais."]'::jsonb, '["ATUALIZAÇÃO: o inciso VII (progressão especial das mulheres) foi incluído por lei posterior."]'::jsonb, 'O Depen mantém o cadastro nacional de vagas prisionais.', '["Assertiva que atribui ao Depen apenas a gestão dos presídios estaduais erra: coordena os federais e apoia os estaduais."]'::jsonb, '[]'::jsonb, '["Art. 71"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-72' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '49344a825f22fe2fc0278066792d08e1404d0a05b6f2c964e54b8b76adf7ef8c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A legislação local poderá criar Departamento Penitenciário ou órgão similar, com as atribuições que estabelecer.', '["Departamento Penitenciário local por lei local."]'::jsonb, '["Faculdade da legislação local."]'::jsonb, 'O Estado cria por lei seu Departamento Penitenciário.', '["Assertiva que obriga todos os Estados a criar o Departamento erra: é possibilidade."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-73' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3ae10e683c9fb84769503f8733f3f339ce30597c9cb8ab47bb0d6e8412cc8114'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Departamento Penitenciário local, ou órgão similar, tem por finalidade supervisionar e coordenar os estabelecimentos penais da Unidade da Federação a que pertencer. Os órgãos realizarão o acompanhamento da progressão especial das mulheres e encaminharão ao Depen os resultados.', '["Supervisionar e coordenar os estabelecimentos do Estado.","Acompanhamento da progressão especial e envio ao Depen."]'::jsonb, '["Âmbito estadual."]'::jsonb, 'O departamento estadual coordena as unidades do Estado.', '["Assertiva que atribui ao departamento local a coordenação dos presídios federais erra."]'::jsonb, '[]'::jsonb, '["Art. 73"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-74' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '053dea22cac3ab65d42a4f35c84d54bc11a257705c2211042e22b63383332817'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O ocupante do cargo de diretor de estabelecimento deverá ser portador de diploma de nível superior de Direito, Psicologia, Ciências Sociais, Pedagogia ou Serviços Sociais; possuir experiência administrativa na área; e ter idoneidade moral e reconhecida aptidão. O diretor deverá residir no estabelecimento, ou nas proximidades, e dedicará tempo integral à sua função.', '["Nível superior em Direito, Psicologia, Ciências Sociais, Pedagogia ou Serviços Sociais.","Experiência administrativa.","Idoneidade moral.","Residência no estabelecimento ou nas proximidades e tempo integral."]'::jsonb, '["Dedicação em TEMPO INTEGRAL."]'::jsonb, 'O diretor com diploma em Pedagogia e experiência administrativa pode assumir a unidade.', '["Assertiva que exige diploma apenas em Direito para o diretor erra: há outras formações."]'::jsonb, '[]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-75' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '07073d71c1d189051a987c69742ca9d6b41ba31570529186d37073026189acd1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
