insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Haverá, em cada comarca, um Conselho da Comunidade composto, no mínimo, por 1 representante de associação comercial ou industrial, 1 advogado indicado pela Seção da Ordem dos Advogados do Brasil, 1 Defensor Público indicado pelo Defensor Público Geral e 1 assistente social escolhido pela Delegacia Seccional do Conselho Nacional de Assistentes Sociais. Na falta da representação, a escolha dos integrantes fica a critério do Juiz da execução.', '["Um Conselho da Comunidade por comarca.","Composição mínima: representante comercial ou industrial, advogado, defensor público e assistente social.","Falta de representação: escolha do juiz."]'::jsonb, '["Composição mínima de QUATRO membros."]'::jsonb, 'O Conselho da Comunidade tem representante da OAB e da Defensoria.', '["Assertiva que dispensa o assistente social na composição mínima erra."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
